selector_to_html = {"a[href=\"#c\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u4f7f\u7528 C++ \u5c01\u88c5\u7684\u7b97\u5b50\u83b7\u5f97\u66f4\u597d\u7684\u6027\u80fd<a class=\"headerlink\" href=\"#c\" title=\"Link to this heading\">#</a></h1><p>\u4f7f\u7528 <em>FlagGems</em> \u65f6\u7684\u53e6\u4e00\u6761\u9ad8\u7ea7\u7684\u4f18\u5316\u8def\u5f84\u662f\u9488\u5bf9\u6240\u9009\u7684\u64cd\u4f5c\u4f7f\u7528\u5176\u4e2d\u7684<strong>C++ \u5c01\u88c5\u7684\u7b97\u5b50</strong>\u3002\n\u5c3d\u7ba1 Triton \u5185\u6838\u901a\u5e38\u80fd\u591f\u7ed9\u51fa\u76f8\u5f53\u4e0d\u9519\u7684\u8ba1\u7b97\u6027\u80fd\uff0cTriton \u672c\u8eab\u662f\u4f7f\u7528 Python \u5b9e\u73b0\u7684 DSL\u3002\n\u8fd9\u610f\u5473\u7740\u7b97\u5b50\u7684\u5b9a\u4e49\u4ee5\u53ca\u7b97\u5b50\u7684\u8fd0\u884c\u65f6\u6d3e\u53d1\u673a\u5236\u90fd\u662f\u7528 Python \u7f16\u5199\u7684\uff0c\n\u56e0\u6b64\u5728\u5ef6\u8fdf\u975e\u5e38\u654f\u611f\u6216\u8005\u5bf9\u541e\u5410\u8981\u6c42\u6781\u4e3a\u82db\u523b\u7684\u573a\u666f\u4e0b\u4f1a\u5b58\u5728<strong>\u4e0d\u53ef\u5ffd\u89c6\u7684\u6027\u80fd\u5f00\u9500</strong>\u3002</p><p>\u4e3a\u4e86\u89e3\u51b3\u8fd9\u4e00\u95ee\u9898\uff0c<em>FlagGems</em> \u63d0\u4f9b\u4e86\u4e00\u5957 C++ \u8fd0\u884c\u65f6\u89e3\u51b3\u65b9\u6848\uff0c\u7528 C++\n\u8bed\u8a00\u6765\u5b9e\u73b0\u7b97\u5b50\u7684\u5c01\u88c5\u903b\u8f91\u3001\u6ce8\u518c\u673a\u5236\u548c\u8fd0\u884c\u65f6\u7ba1\u7406\uff0c\u4e0e\u6b64\u540c\u65f6\u4ecd\u7136\u590d\u7528\u4e0b\u5c42\u7684 Triton \u5185\u6838\u6765\u5b8c\u6210\u5b9e\u9645\u8ba1\u7b97\u3002\n\u8fd9\u79cd\u65b9\u6cd5\u80fd\u591f\u4fdd\u7559 Triton \u4e2d\u5185\u6838\u7ea7\u522b\u7684\u6548\u7387\uff0c\u540c\u65f6\u5927\u5e45\u964d\u4f4e Python \u8bed\u8a00\u76f8\u5173\u7684\u6027\u80fd\u5f00\u9500\uff0c\n\u4f7f\u5f97\u7528\u6237\u80fd\u591f\u4e0e\u5e95\u5c42\u7684 CUDA \u5de5\u4f5c\u6d41\u8fdb\u884c\u66f4\u4e3a\u7d27\u5bc6\u7684\u96c6\u6210\uff0c\u63d0\u5347\u6574\u4f53\u7684\u63a8\u7406\u6027\u80fd\u3002</p>", "a[href=\"#aten-dispatcher-torch\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.2 \u901a\u8fc7 ATen \u76f4\u63a5\u66ff\u6362\uff08\u5728 dispatcher \u5c42\u9762\u900f\u660e\u63a5\u7ba1 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.*</span></code>\uff09<a class=\"headerlink\" href=\"#aten-dispatcher-torch\" title=\"Link to this heading\">#</a></h3><p>\u5bf9\u4e8e\u5176\u4e2d\u7684\u4e00\u90e8\u5206\u7b97\u5b50\uff0c<em>FlagGems</em> \u8fd8\u4f1a\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">src/flag_gems/csrc/aten_patch.cpp</span></code>\n\u4e2d\u4f7f\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">TORCH_LIBRARY_IMPL(aten,</span> <span class=\"pre\">&lt;dispatch_key&gt;,</span> <span class=\"pre\">m)</span></code> \u628a C++ \u5b9e\u73b0\n<strong>\u76f4\u63a5\u6ce8\u518c\u5230 <code class=\"docutils literal notranslate\"><span class=\"pre\">aten::</span></code> \u540d\u5b57\u7a7a\u95f4</strong>\u3002\u5177\u4f53\u7684 dispatch key \u6309\u540e\u7aef\u9009\u62e9\uff1a</p>", "a[href=\"#c-operators-pybind-dispatcher\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.3 \u901a\u8fc7 <code class=\"docutils literal notranslate\"><span class=\"pre\">c_operators</span></code> pybind \u6a21\u5757\uff08\u76f4\u8fde\u3001\u4e0d\u7ecf dispatcher\uff09<a class=\"headerlink\" href=\"#c-operators-pybind-dispatcher\" title=\"Link to this heading\">#</a></h3><p>\u540c\u6837\u7684\u4e00\u7ec4 C++ \u5c01\u88c5\u7b97\u5b50\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">src/flag_gems/csrc/cstub.cpp</span></code> \u4e2d\u8fd8\u4f1a\u901a\u8fc7\n<code class=\"docutils literal notranslate\"><span class=\"pre\">PYBIND11_MODULE(c_operators,</span> <span class=\"pre\">\u2026)</span></code> \u5bfc\u51fa\u4e3a\u4e00\u4e2a Python \u6269\u5c55\u6a21\u5757\uff1a</p>", "a[href=\"#torch-ops-flag-gems\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.1 \u901a\u8fc7 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.ops.flag_gems.*</span></code>\uff08\u81ea\u5b9a\u4e49\u7b97\u5b50\u540d\u5b57\u7a7a\u95f4\uff09<a class=\"headerlink\" href=\"#torch-ops-flag-gems\" title=\"Link to this heading\">#</a></h3><p>\u6240\u6709 C++ \u5c01\u88c5\u7b97\u5b50\u90fd\u4f1a\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">src/flag_gems/csrc/cstub.cpp</span></code> \u4e2d\u901a\u8fc7\n<code class=\"docutils literal notranslate\"><span class=\"pre\">TORCH_LIBRARY(flag_gems,</span> <span class=\"pre\">m)</span></code> \u6ce8\u518c\u4e3a PyTorch \u7684<strong>\u81ea\u5b9a\u4e49\u7b97\u5b50\uff08custom op\uff09</strong>\uff0c\n\u5f52\u5165 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> \u540d\u5b57\u7a7a\u95f4\u3002\u4f60\u53ef\u4ee5\u5728 Python \u4e2d\u663e\u5f0f\u5730\u8c03\u7528\u5b83\u4eec\uff0c\n\u4ece\u800c\u7ed5\u8fc7\u6240\u6709 patch \u903b\u8f91\u4e0e Python \u4fa7\u7684\u56de\u9000\u8def\u5f84\uff1a</p>", "a[href=\"#id4\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u5c0f\u7ed3<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. \u5b89\u88c5\u4e0e\u542f\u7528<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>\u60f3\u8ba9 C++ wrapper <strong>\u5168\u91cf\u751f\u6548</strong>\uff0c\u9700\u8981\u540c\u65f6\u6ee1\u8db3\u4ee5\u4e0b\u4e24\u6b65\uff1a</p>", "a[href=\"#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u53c2\u8003\uff1a\u76ee\u524d\u652f\u6301\u7684 C++ \u5c01\u88c5\u7684\u7b97\u5b50<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><p>\u4ee5\u4e0b\u7b97\u5b50\u76ee\u524d\u5728 <em>FlagGems</em> \u4e2d\u63d0\u4f9b\u4e86 C++ \u5c01\u88c5\u5b9e\u73b0\u3002</p>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. C++ \u7b97\u5b50\u7684\u56db\u79cd\u8c03\u7528\u65b9\u5f0f<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p>C++ \u6269\u5c55\u6784\u5efa\u5b8c\u6210\u4e4b\u540e\uff0c\u540c\u4e00\u4efd\u5e95\u5c42 C++ \u5c01\u88c5\u7b97\u5b50\u5b9e\u9645\u4e0a\u53ef\u4ee5\u901a\u8fc7<strong>\u56db\u79cd</strong>\n\u4e0d\u540c\u7684\u65b9\u5f0f\u88ab\u8c03\u7528\u3002\u8fd9\u51e0\u79cd\u65b9\u5f0f\u9762\u5411\u4e0d\u540c\u7684\u4f7f\u7528\u573a\u666f\uff0c\u5e76\u4e14\u5206\u522b\u6709\u7740\u4e0d\u540c\u7684 dispatcher \u5f00\u9500\u3002</p>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. \u67b6\u6784<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> \u4e2d C++ \u5c01\u88c5\u7684\u7b97\u5b50\u6784\u5efa\u4e8e\n<a class=\"reference external\" href=\"https://github.com/flagos-ai/libtriton_jit\"><code class=\"docutils literal notranslate\"><span class=\"pre\">libtriton_jit</span></code></a> \u4e4b\u4e0a\u3002\n<code class=\"docutils literal notranslate\"><span class=\"pre\">libtriton_jit</span></code> \u662f\u4e00\u4e2a\u591a\u540e\u7aef\u7684 Triton JIT C++ \u8fd0\u884c\u65f6\uff0c\u5b83\u5728 C++ \u4e2d\u91cd\u65b0\u5b9e\u73b0\u4e86\nTriton JIT \u8fd0\u884c\u65f6\u903b\u8f91\uff08\u53c2\u6570\u7279\u5316\u3001\u5185\u6838\u7f13\u5b58\u548c\u53d1\u5c04\uff09\uff0c\n\u800c\u5b9e\u9645\u7684 kernel \u7f16\u8bd1\u4ecd\u7136\u59d4\u6258\u7ed9\u4e0a\u6e38\u7684 Triton \u7f16\u8bd1\u5668\u5b8c\u6210\u3002</p><p>\u5728\u8fd9\u4e00\u6574\u5957\u6280\u672f\u6808\u4e2d\uff1a</p>", "a[href=\"#c-api-flag-gems-gtest\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.4 \u901a\u8fc7\u539f\u751f C++ API\uff08<code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems::</span></code> \u51fd\u6570\u4e0e GTest\uff09<a class=\"headerlink\" href=\"#c-api-flag-gems-gtest\" title=\"Link to this heading\">#</a></h3><p>\u6bcf\u4e00\u4e2a\u5c01\u88c5\u7b97\u5b50\u672c\u8eab\u90fd\u662f\u4e00\u4e2a\u666e\u901a\u7684 C++ \u51fd\u6570\uff0c\u4f4d\u4e8e <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems::</span></code> \u540d\u5b57\u7a7a\u95f4\uff0c\n\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">include/flag_gems/operators.h</span></code> \u4e2d\u58f0\u660e\uff0c\u5e76\u968f\u5b89\u88c5\u51fa\u7684 CMake \u76ee\u6807\n<code class=\"docutils literal notranslate\"><span class=\"pre\">FlagGems::operators</span></code> \u4e00\u8d77\u53d1\u5e03\u3002\u4e0b\u6e38\u7684 C++ \u4ee3\u7801\u53ef\u4ee5\u76f4\u63a5\u94fe\u63a5\u8be5\u76ee\u6807\u5e76\u8c03\u7528\uff1a</p>"}
